{
    "predictors": [
        {
            "name": "Digital Presence Intensity",
            "construction": "Calculate the number of mentions a company receives in online forums and digital newspapers over the past year, scaled by its market capitalization.",
            "rationale": "Firms with higher digital presence might signal increased investor interest and potential demand shifts.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "R&D to Market Cap Ratio",
            "construction": "Divide the firm's annual Research and Development expenses by its market capitalization at the end of the fiscal year.",
            "rationale": "Firms investing heavily in R&D relative to their size could be undervalued if markets underestimate their growth potential.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Strategic Alliances Count",
            "construction": "Count the number of strategic alliances and partnerships announced by a firm over the past year.",
            "rationale": "Firms forming more alliances may gain competitive advantages and enhanced market positioning.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Concentration Risk",
            "construction": "Calculate the percentage of revenue attributed to the top 5 customers, based on the last annual report.",
            "rationale": "High customer concentration might imply risk which, if resolved, leads to higher returns.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Patent Citation Impact",
            "construction": "Assess the number of citations per patent a firm has received in the last 5 years.",
            "rationale": "Highly cited patents suggest technological leadership and potential for future earnings growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Environmental Compliance Ratio",
            "construction": "Divide the number of positive environmental compliance reports by total reports over the past three years.",
            "rationale": "A better compliance record can indicate effective management and potential cost savings.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Satisfaction Index",
            "construction": "Use surveys or third-party reports to score employee satisfaction on a scale from 1 to 10.",
            "rationale": "Higher employee satisfaction can lead to increased productivity and innovation.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Foreign Revenue Proportion",
            "construction": "Calculate the percentage of revenue derived from foreign markets as stated in the latest financial report.",
            "rationale": "Higher foreign revenue can indicate diversification and potential growth in emerging markets.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Corporate Social Responsibility Score",
            "construction": "Aggregate a score based on various social responsibility initiatives and community engagement metrics.",
            "rationale": "Firms with strong CSR initiatives may attract more investors and enjoy better reputational capital.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "CEO Media Exposure",
            "construction": "Count the number of media appearances by the CEO in major outlets over the past year.",
            "rationale": "Increased CEO visibility can enhance firm reputation and signal transparency to investors.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
